import { db } from './firebase';

export const apiService = {
  // Submit Contact Form directly to Firebase Firestore
  submitContactForm: async (data) => {
    if (db) {
      const now = new Date();
      const timestampStr = now.getFullYear() + '-' +
        String(now.getMonth() + 1).padStart(2, '0') + '-' +
        String(now.getDate()).padStart(2, '0') + ' ' +
        String(now.getHours()).padStart(2, '0') + ':' +
        String(now.getMinutes()).padStart(2, '0') + ':' +
        String(now.getSeconds()).padStart(2, '0');

      await db.collection("customer_inquiries").add({
        name: data.name || 'Anonymous Customer',
        phone: data.phone || '',
        email: data.email || '',
        service: data.service || 'General Inquiry',
        message: data.message || '',
        timestamp: timestampStr,
        status: "Pending"
      });
    }
    return { status: "success", message: "Message received!" };
  },

  // Fetch Message inquiries directly from Firebase Firestore
  getMessages: async () => {
    if (!db) return [];
    try {
      const msgSnap = await db.collection("customer_inquiries").orderBy("timestamp", "desc").get();
      const list = [];
      msgSnap.forEach(doc => list.push({ id: doc.id, ...doc.data() }));
      return list;
    } catch (e) {
      console.warn("Firestore fetch error:", e.message);
      return [];
    }
  },

  // Fetch Overview Stats directly from Firebase Firestore
  getStats: async () => {
    if (!db) return { totalMessages: 0, totalUsers: 0, totalLogs: 0 };
    try {
      const usersSnap = await db.collection("users").get();
      const msgSnap = await db.collection("customer_inquiries").get();
      const logsSnap = await db.collection("history").get();
      return {
        totalUsers: usersSnap.size,
        totalMessages: msgSnap.size,
        totalLogs: logsSnap.size
      };
    } catch (e) {
      return { totalMessages: 0, totalUsers: 0, totalLogs: 0 };
    }
  }
};

export default apiService;
